import{Base,fmt}from'./base.js';import{clamp,dist,area,angle,polygonAngles,heron}from'../math.js';
export default class Geometry extends Base{
 constructor(host,ctx){super(host,ctx);this.id=ctx.chapter.id;this.mode=ctx.scene.id;this.points=[[-3,-2],[3,-2],[0,3]];this.theta=50;this.offset=1;
 if(this.id===5||this.id===11){this.points=[];this.button('Next step →','अगला चरण →',()=>this.step=(this.step+1)%6)}
 if(this.id===6){this.slider('theta','Transversal angle','तिर्यक छेदी कोण',15,165,50,1,'°');this.select('pair',{label:'Angle pairs | कोण युग्म',items:[['corresponding','Corresponding','संगत'],['alternate','Alternate interior','एकांतर अंतः'],['cointerior','Co-interior','एक ही ओर के अंतः']]},'corresponding')}
 if(this.id===7)this.select('congruence',{label:'Triangle mode | त्रिभुज प्रकार',items:[['single','Single triangle','1 त्रिभुज'],['check','Congruence checker (SSS)','सर्वांगसमता जाँच (SSS)']]},this.mode==='congruence'?'check':'single');
 if(this.id===8){this.points=[[-3,-2],[3,-2],[2,2],[-2,3]];this.select('snap',{label:'Shape | आकृति',items:[['free','Free quadrilateral','स्वतंत्र चतुर्भुज'],['square','Square','वर्ग'],['rectangle','Rectangle','आयत'],['parallelogram','Parallelogram','समांतर चतुर्भुज'],['rhombus','Rhombus','समचतुर्भुज']]},'free')}
 if(this.id===9){this.slider('offset','Top-side shift','ऊपरी भुजा का खिसकाव',-3,3,1,.1);this.points=[[-4,-2],[1,-2],[2,2],[-3,2]]}
 if(this.id===10){this.points=[[3,0],[-1.5,1.5*Math.sqrt(3)],[-1.5,-1.5*Math.sqrt(3)]];this.slider('arc','Minor central angle','लघु केंद्रीय कोण',30,160,120,1,'°')}
 if(this.id===7){this.other=[[1,-1],[4,-1],[2.5,1.5]];this.reference=this.points.map(p=>[...p]);this.button('Match reference triangle','संदर्भ त्रिभुज मिलाएँ',()=>{this.other=this.reference.map(p=>[p[0]+.6,p[1]-.4])})}
 this.draw()}
 update(k){if(this.id===8&&k==='snap'){let shapes={square:[[-2,-2],[2,-2],[2,2],[-2,2]],rectangle:[[-3,-2],[3,-2],[3,2],[-3,2]],parallelogram:[[-3,-2],[2,-2],[3,2],[-2,2]],rhombus:[[-3,0],[0,-2],[3,0],[0,2]]};if(shapes[this.snap])this.points=shapes[this.snap].map(p=>[...p])}if(this.id===10){let a=this.arc*Math.PI/180;this.points[0]=[3,0];this.points[1]=[3*Math.cos(a),3*Math.sin(a)]}}
 move(i,p){p=p.map(v=>clamp(v,-7,7));if(this.id===6){this.theta=clamp(Math.atan2(p[1]+1,p[0])*180/Math.PI,15,165);return}if(this.id===9){this.offset=clamp(p[0]+4,-3,3);return}if(this.id===10){let a=Math.atan2(p[1],p[0]);if(i===2){if(a>-.15)a=-.15;if(a< -Math.PI+.15)a=-Math.PI+.15;this.points[i]=[3*Math.cos(a),3*Math.sin(a)]}else if(i===1){this.arc=clamp(a*180/Math.PI,30,160);this.update()}return}if(this.id===7&&this.congruence==='check'){this.other[i]=p;return}if(this.id===8&&this.snap!=='free'){this.snap='free';this.controls.querySelector('select').value='free'}this.points[i]=p}
 draw(){this.clear();if(this.id===5||this.id===11)return this.drawSteps();if(this.id===6)return this.drawAngles();if(this.id===9)return this.drawArea();if(this.id===10)return this.drawCircle();let t=this.ctx.t,p=this.id===7&&this.congruence==='check'?this.other:this.points;
 this.path(p,'shape',true);p.forEach((v,i)=>this.point(v,i,String.fromCharCode(65+i)));let sides=p.map((v,i)=>dist(v,p[(i+1)%p.length])),angles=polygonAngles(p);if(this.labels)p.forEach((v,i)=>{let b=p[(i+1)%p.length];this.text([(v[0]+b[0])/2+.15,(v[1]+b[1])/2+.2],fmt(sides[i]))});let A=area(p),out=`${t('Sides','भुजाएँ')}: ${sides.map(fmt).join(', ')} ${t('units','इकाई')}\n${t('Angles','कोण')}: ${angles.map(v=>fmt(v)+'°').join(', ')}\nΣ = ${fmt(angles.reduce((a,b)=>a+b,0))}°; ${t('Area','क्षेत्रफल')} = ${fmt(A)} ${t('square units','वर्ग इकाई')}`;
 if(this.id===8){let cross=[];for(let i=0;i<4;i++){let[a,b,c]=[p[i],p[(i+1)%4],p[(i+2)%4]];cross.push((b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]))}let intersect=(a,b,c,d)=>{let cr=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);return cr(a,b,c)*cr(a,b,d)<0&&cr(c,d,a)*cr(c,d,b)<0};if(intersect(p[0],p[1],p[2],p[3])||intersect(p[1],p[2],p[3],p[0]))out=t('Crossed polygon: the simple quadrilateral angle-sum theorem does not apply. Move vertices to uncross the sides.','भुजाएँ कट रही हैं: सरल चतुर्भुज का कोण-योग प्रमेय लागू नहीं है। शीर्षों को खिसकाएँ।');else if(cross.some(x=>Math.abs(x)<1e-7))out=t('Degenerate quadrilateral: 3 consecutive vertices are collinear.','विकृत चतुर्भुज: 3 लगातार शीर्ष संरेख हैं।');else out+='\n'+t('Simple quadrilateral: sum of interior angles = 360°. Snap is a starting template; dragging releases it.','सरल चतुर्भुज: अंतःकोणों का योग = 360°। साँचा चुनने के बाद खींचने पर आकृति स्वतंत्र हो जाती है।')}
 if(this.id===7&&this.congruence==='check'){this.path(this.reference,'shape',true,{'stroke-dasharray':'6 4',stroke:'#f5c366',fill:'none'});let r=this.reference.map((v,i)=>dist(v,this.reference[(i+1)%3])).sort((a,b)=>a-b),s=[...sides].sort((a,b)=>a-b),equal=r.every((v,i)=>Math.abs(v-s[i])<.025);out+='\n'+t('Gold dashed triangle = reference.','सुनहरा बिंदीदार त्रिभुज = संदर्भ।')+'\n'+t(equal?'SSS matches within 0.025 units: congruent at display precision.':'SSS does not match: triangles are not congruent.',equal?'SSS 0.025 इकाई की सीमा में समान: प्रदर्शित परिशुद्धता पर सर्वांगसम।':'SSS समान नहीं: त्रिभुज सर्वांगसम नहीं हैं।')}
 if(this.id===12){let h=heron(...sides);out+=h.valid?`\ns = (${sides.map(fmt).join(' + ')}) / 2 = ${fmt(h.s)}\nA = √[s(s−a)(s−b)(s−c)]\n= √[${fmt(h.s)} × ${sides.map(v=>fmt(h.s-v)).join(' × ')}]\n= ${fmt(h.area)} ${t('square units','वर्ग इकाई')}`:'\n'+t('Degenerate triangle: triangle inequality must be strict. Area = 0.','विकृत त्रिभुज: त्रिभुज असमिका सख्त होनी चाहिए। क्षेत्रफल = 0।')}
 this.output(out)}
 drawAngles(){let t=this.ctx.t,a=this.theta*Math.PI/180,u=[Math.cos(a),Math.sin(a)],lower=[0,-1],upper=[2/Math.tan(a),1];this.line([-9,-1],[9,-1]);this.line([-9,1],[9,1]);this.line([-u[0]*14,-1-u[1]*14],[u[0]*14,-1+u[1]*14]);this.points=[[u[0]*4,-1+u[1]*4]];this.point(this.points[0],0,'P');let vals=[this.theta,180-this.theta,this.theta,180-this.theta,this.theta,180-this.theta,this.theta,180-this.theta],positions=[[.55,.35],[-1.2,.35],[-1.2,-.6],[.55,-.6]],highlight={corresponding:[0,4],alternate:[2,4],cointerior:[3,4]}[this.pair];[upper,lower].forEach((p,j)=>positions.forEach((d,k)=>{let i=j*4+k;this.text([p[0]+d[0],p[1]+d[1]],`${i+1}: ${fmt(vals[i])}°`,{style:highlight.includes(i)?'fill:#f5c366;font-weight:bold':''})}));this.output(vals.map((v,i)=>`∠${i+1} = ${fmt(v)}°`).join(' · ')+`\n${t('Highlighted angles','चिह्नित कोण')}: ∠${highlight[0]+1}, ∠${highlight[1]+1}\n`+t(this.pair==='cointerior'?'Co-interior sum = 180°.':'Corresponding / alternate interior angles are equal.',this.pair==='cointerior'?'एक ही ओर के अंतःकोणों का योग = 180°।':'संगत / एकांतर अंतःकोण बराबर हैं।'))}
 drawArea(){let p=[[-6,-2],[-1,-2],[-1+this.offset,2],[-6+this.offset,2]];this.path(p,'shape',true);this.points=[p[3]];this.point(p[3],0,'D');this.line([-8,2],[8,2],'axis',{'stroke-dasharray':'5 4'});let q=[[2,-2],[7,-2],[4+this.offset/3,2]];this.path(q,'shape',true);this.line([0,-2],[0,2],'gold',{'stroke-dasharray':'4 4'});this.text([-.1,0],'h = 4');this.text([-5,-2.7],'b = 5');this.text([3,-2.7],'b = 5');this.output(this.ctx.t('Same base and height:','समान आधार और ऊँचाई:')+'\n'+this.ctx.t('Parallelogram','समांतर चतुर्भुज')+' = b × h = 5 × 4 = 20\n'+this.ctx.t('Triangle','त्रिभुज')+' = ½bh = 10\n'+this.ctx.t('Slide the gold top vertex horizontally. Both areas stay fixed.','सुनहरा ऊपरी शीर्ष क्षैतिज खिसकाएँ। दोनों क्षेत्रफल स्थिर रहते हैं।'))}
 drawCircle(){let t=this.ctx.t,[a,b,c]=this.points;this.circle([0,0],3,'shape',{fill:'none'});this.line([0,0],a);this.line([0,0],b);this.line(c,a);this.line(c,b);this.line(a,b);let m=[(a[0]+b[0])/2,(a[1]+b[1])/2];this.line([0,0],m,'gold',{'stroke-dasharray':'5 4'});this.circle(m,.1,'gold');if(this.labels){this.text([m[0]+.2,m[1]+.2],'M');this.text([.2,-.5],'O')}this.point(b,1,'B');this.point(c,2,'C');this.output(`∠AOB = ${fmt(this.arc)}°\n∠ACB = ${fmt(angle(a,c,b))}° = ½∠AOB\nAM = MB = ${fmt(dist(a,m))}\n`+t('OM is perpendicular to chord AB. C is constrained to the opposite arc. Drag B or C.','OM जीवा AB पर लंब है। C को विपरीत चाप पर रखा गया है। B या C खींचें।'))}
 drawSteps(){this.clear(false);let t=this.ctx.t,steps;
 if(this.id===5){let a=[-4,0],b=[4,0],c=[0,0];this.line(a,b);this.circle(c,.1,'gold');this.text([-4,-.5],'A');this.text([4,-.5],'B');this.text([0,-.5],'O');if(this.step>=1)this.line(c,[2,3]);if(this.step>=2){this.text([-2,1],'x');this.text([2,1],'y')}if(this.step>=4)this.text([-2,2.5],'x + y = 180°');steps=[t('Given: A, O, B lie on a straight line.','दिया है: A, O, B एक सरल रेखा पर हैं।'),t('Draw ray OC on one side of AB.','AB की एक ओर किरण OC बनाएँ।'),t('Let ∠AOC = x and ∠COB = y.','मान लें ∠AOC = x और ∠COB = y।'),t('The whole equals the sum of its non-overlapping parts.','संपूर्ण अपने न अतिव्यापी भागों के योग के बराबर है।'),t('A straight angle is 180°; therefore x + y = 180°.','सरल कोण 180° है; इसलिए x + y = 180°।'),t('Conclusion: adjacent angles on a line form a linear pair. The picture illustrates; the stated facts justify the proof.','निष्कर्ष: रेखा पर आसन्न कोण रैखिक युग्म बनाते हैं। चित्र समझाता है; दिए गए तथ्य प्रमाण का आधार हैं।')]}
 else if(this.mode==='bisector'){let a=[-3,0],b=[3,0],u=[0,Math.sqrt(7)],v=[0,-Math.sqrt(7)];this.line(a,b);this.text([-3,-.5],'A');this.text([3,-.5],'B');if(this.step>=1)this.circle(a,4,'shape',{fill:'none','stroke-dasharray':'4 4'});if(this.step>=2)this.circle(b,4,'shape',{fill:'none','stroke-dasharray':'4 4'});if(this.step>=3){this.circle(u,.12,'gold');this.circle(v,.12,'gold');this.text([.2,3],'P');this.text([.2,-3],'Q')}if(this.step>=4)this.line([0,-4],[0,4],'gold');steps=[t('Draw segment AB = 6 units.','AB = 6 इकाई का रेखाखंड बनाएँ।'),t('Set compass radius 4 (> half of AB); draw arcs centred at A.','परकार की त्रिज्या 4 (AB के आधे से अधिक) रखें; A केंद्र से चाप खींचें।'),t('Keep radius unchanged; draw arcs centred at B.','त्रिज्या बदले बिना B केंद्र से चाप खींचें।'),t('Label the arc intersections P and Q.','चापों के प्रतिच्छेद P और Q नामित करें।'),t('Join PQ with a ruler. PQ bisects AB at right angles.','पटरी से PQ मिलाएँ। PQ, AB का लंब समद्विभाजक है।'),t('Reason: PA = PB and QA = QB; the common line is the perpendicular bisector.','कारण: PA = PB और QA = QB; उभयनिष्ठ रेखा लंब समद्विभाजक है।')]}
 else{let a=[0,0],b=[4,0],c=[2,Math.sqrt(12)];this.line(a,b);if(this.step>=1)this.circle(a,4,'shape',{fill:'none','stroke-dasharray':'4 4'});if(this.step>=2)this.circle(b,4,'shape',{fill:'none','stroke-dasharray':'4 4'});if(this.step>=3){this.circle(c,.12,'gold');this.text([2.2,3.6],'C')}if(this.step>=4){this.line(a,c);this.line(b,c)}steps=[t('Draw AB = 4 units.','AB = 4 इकाई बनाएँ।'),t('With A as centre and radius AB, draw an arc.','A केंद्र और AB त्रिज्या से चाप खींचें।'),t('With B as centre and the same radius, draw another arc.','B केंद्र और उसी त्रिज्या से दूसरा चाप खींचें।'),t('Mark one intersection as C.','1 प्रतिच्छेद का नाम C रखें।'),t('Join AC and BC. All 3 sides equal 4 units.','AC और BC मिलाएँ। तीनों भुजाएँ 4 इकाई हैं।'),t('ABC is equilateral. Each angle is 60°. Arcs are compass traces, not extra sides.','ABC समबाहु है। प्रत्येक कोण 60° है। चाप परकार के निशान हैं, अतिरिक्त भुजाएँ नहीं।')]}
 this.output(`${t('Step','चरण')} ${this.step+1} / 6\n${steps[this.step]}`)}
}
